// Splits a bill (in agorot, a whole number) between people by weights.
function parseDecimal(n) {
  const [mantissa, expPart] = String(n).split(/[eE]/);
  const exp = expPart ? parseInt(expPart, 10) : 0;
  const dot = mantissa.indexOf(".");
  if (dot === -1) return { digits: BigInt(mantissa), exp };
  return {
    digits: BigInt(mantissa.slice(0, dot) + mantissa.slice(dot + 1)),
    exp: exp - (mantissa.length - dot - 1),
  };
}

function splitBill(total, weights) {
  if (!Number.isInteger(total) || total < 0) throw new Error("bad total");
  if (!Array.isArray(weights) || !weights.length || weights.some((w) => !Number.isFinite(w) || !(w > 0))) {
    throw new Error("bad weights");
  }

  const parsed = weights.map(parseDecimal);
  let minExp = parsed[0].exp;
  for (let i = 1; i < parsed.length; i++) {
    if (parsed[i].exp < minExp) minExp = parsed[i].exp;
  }

  const scaled = parsed.map((p) => p.digits * (10n ** BigInt(p.exp - minExp)));
  const sum = scaled.reduce((a, b) => a + b, 0n);
  const totalBig = BigInt(total);

  const shares = new Array(weights.length);
  const rems = new Array(weights.length);
  let floorSum = 0n;

  for (let i = 0; i < scaled.length; i++) {
    const num = totalBig * scaled[i];
    shares[i] = num / sum;
    rems[i] = num % sum;
    floorSum += shares[i];
  }

  const leftover = Number(totalBig - floorSum);
  const order = Array.from({ length: weights.length }, (_, i) => i);
  order.sort((a, b) => (rems[b] > rems[a] ? 1 : rems[b] < rems[a] ? -1 : a - b));

  for (let i = 0; i < leftover; i++) {
    shares[order[i]] += 1n;
  }

  return shares.map(Number);
}

module.exports = { splitBill };
