function parseDecimal(num) {
  const [coeff, expPart] = String(num).split(/[eE]/);
  let exp = expPart ? Number(expPart) : 0;
  const dotIdx = coeff.indexOf(".");
  let digits = coeff;
  if (dotIdx !== -1) {
    exp -= coeff.length - dotIdx - 1;
    digits = coeff.slice(0, dotIdx) + coeff.slice(dotIdx + 1);
  }
  return { mantissa: BigInt(digits), exp };
}

function splitBill(total, weights) {
  if (!Number.isInteger(total) || total < 0) throw new Error("bad total");
  if (!Array.isArray(weights) || !weights.length || weights.some((w) => !Number.isFinite(w) || w <= 0)) {
    throw new Error("bad weights");
  }

  const parsed = weights.map(parseDecimal);
  const minExp = parsed.reduce((min, p) => (p.exp < min ? p.exp : min), parsed[0].exp);
  const scaled = parsed.map((p) => p.mantissa * (10n ** BigInt(p.exp - minExp)));
  const sum = scaled.reduce((a, b) => a + b, 0n);

  const totalBig = BigInt(total);
  const shares = new Array(weights.length);
  const rems = new Array(weights.length);
  let floorSum = 0n;

  for (let i = 0; i < scaled.length; i++) {
    const num = totalBig * scaled[i];
    const floor = num / sum;
    shares[i] = Number(floor);
    rems[i] = num % sum;
    floorSum += floor;
  }

  const leftover = Number(totalBig - floorSum);
  const indices = Array.from({ length: weights.length }, (_, i) => i);
  indices.sort((a, b) => {
    if (rems[b] > rems[a]) return 1;
    if (rems[b] < rems[a]) return -1;
    return a - b;
  });

  for (let i = 0; i < leftover; i++) {
    shares[indices[i]] += 1;
  }

  return shares;
}

module.exports = { splitBill };
